<script setup lang="ts">
import { Settings2, Sun, Moon, Monitor, PenLine, Database, Download, Upload, Check, RefreshCw, ArrowUpRight } from 'lucide-vue-next'
import type { SiteSettings, ThemePreference } from '#shared/workspace'
import type { ImportPlan } from '#shared/workspace'
const route = useRoute(); const router = useRouter()
const { data: workspace, error: workspaceError, status: workspaceStatus, refresh } = await useAdminWorkspace()
const { data: dataInfo, error: dataError, status: dataStatus, refresh: refreshData } = await useAdminData<{ content: number; bases: number; terms: number; assets: number; operations: { action: string; detail: string; success: boolean; at: string }[] } | null>('/api/admin/data', null)
type AgentCredential = { id: string; name: string; scopes: string[]; createdAt: number; expiresAt: number; revokedAt: number | null }
const { data: agentCredentials, error: credentialError, status: credentialStatus, refresh: refreshAgentCredentials } = await useAdminData<AgentCredential[]>('/api/admin/agent-credentials', [])
const credentialName = ref(''); const credentialToken = ref(''); const credentialBusy = ref(false)
const credentialAction = ref(''); const credentialId = ref('')
const credentialScopes = ref(['content:read', 'content:write', 'content:publish', 'taxonomy:write'])
const credentialScopeOptions = [{ id: 'content:read', name: '读取内容和历史' }, { id: 'content:write', name: '保存与恢复编辑稿' }, { id: 'content:publish', name: '发布与撤回' }, { id: 'taxonomy:write', name: '管理分类和标签' }]
async function createCredential() {
  if (!credentialName.value.trim() || !credentialScopes.value.length || credentialBusy.value || credentialToken.value) return
  credentialBusy.value = true; credentialAction.value = 'create'; message.value = ''
  try {
    const result = await $fetch<{ token: string }>('/api/admin/agent-credentials', { method: 'POST', body: { action: 'create', name: credentialName.value, scopes: credentialScopes.value } })
    credentialToken.value = result.token; credentialName.value = ''; message.value = '凭据已创建，请立即保存。'; await refreshAgentCredentials()
  } catch (e: any) { message.value = e.data?.statusMessage || '创建结果暂不确定，请检查凭据列表后再试。'; await refreshAgentCredentials() }
  finally { credentialBusy.value = false; credentialAction.value = '' }
}
async function revokeCredential(credential: AgentCredential) {
  if (credentialBusy.value || !window.confirm(`确定撤销“${credential.name}”的 Agent 凭据？使用它的连接将立即失效。`)) return
  credentialBusy.value = true; credentialAction.value = 'revoke'; credentialId.value = credential.id; message.value = ''
  try { await $fetch('/api/admin/agent-credentials', { method: 'POST', body: { action: 'revoke', id: credential.id } }); message.value = '凭据已撤销'; await refreshAgentCredentials() }
  catch (e: any) { message.value = e.data?.statusMessage || '撤销结果暂不确定，请检查凭据列表后再试。'; await refreshAgentCredentials() }
  finally { credentialBusy.value = false; credentialAction.value = ''; credentialId.value = '' }
}
async function copyCredential() {
  try { await navigator.clipboard.writeText(credentialToken.value); message.value = '凭据已复制，请保存到本机钥匙串。' }
  catch { message.value = '复制失败，请手动复制凭据。' }
}
const tab = computed(() => ['general','appearance','editor','data'].includes(String(route.query.tab)) ? String(route.query.tab) : 'general')
const form = ref<SiteSettings | null>(null); const dirty = ref(false); const busy = ref(false); const message = ref('')
const { selection, setTheme, resetTheme } = useTheme()
const choices: { id: ThemePreference; name: string; icon: typeof Sun; caption: string }[] = [{ id: 'light', name: '浅色', icon: Sun, caption: '白底与深色文字' }, { id: 'dark', name: '深色', icon: Moon, caption: '深灰底与柔和文字' }, { id: 'system', name: '跟随系统', icon: Monitor, caption: '自动匹配设备外观' }]
watch(workspace, value => { if (value && !dirty.value) form.value = structuredClone(toRaw(value.settings)) }, { immediate: true })
const types = computed(() => workspace.value?.terms.filter(t => t.kind === 'type' && t.enabled) || [])
const typeOptions = computed(() => types.value.map(type => ({ value: type.id, label: type.name })))
function setDefaultKind(value: string | null) { if (form.value && value) { form.value.defaultKind = value as SiteSettings['defaultKind']; dirty.value = true } }
function changeTab(id: string) { if (dirty.value && id === 'data') { message.value = '请先保存或撤销设置，再进入数据管理'; return }; message.value = ''; void router.replace({ query: { tab: id } }) }
async function save() {
  if (!form.value || !workspace.value) return
  busy.value = true; message.value = ''
  try { const result = await $fetch('/api/admin/settings', { method: 'POST', body: { revision: workspace.value.revision, settings: form.value } }); dirty.value = false; workspace.value = result; form.value = structuredClone(result.settings); await refreshNuxtData('site-workspace'); message.value = '设置已保存' }
  catch (e: any) { message.value = e.data?.statusMessage || '保存失败'; if (e.status === 409) await refresh() }
  finally { busy.value = false }
}
const fileInput = ref<HTMLInputElement>(); const files = ref<File[]>([]); const plan = ref<ImportPlan | null>(null); const restoreSettings = ref(false); const importAt = ref(''); const importing = ref(false); const importAction = ref('')
function fileChanged(event: Event) { files.value = [...((event.target as HTMLInputElement).files || [])]; plan.value = null; importAt.value = new Date().toISOString(); message.value = '' }
watch(restoreSettings, () => { plan.value = null })
async function runImport(action: 'plan' | 'apply') {
  if (!files.value.length || importing.value) return
  importing.value = true; importAction.value = action; message.value = ''
  const data = new FormData(); for (const file of files.value) data.append('file', file)
  data.append('action', action); data.append('restoreSettings', String(restoreSettings.value)); data.append('importedAt', importAt.value)
  if (plan.value) data.append('token', plan.value.token)
  try {
    const result = await $fetch<{ plan?: ImportPlan; result?: { imported: number; skipped: number; knowledge: number } }, string>('/api/admin/import', { method: 'POST', body: data })
    if (result.plan) plan.value = result.plan
    else if (result.result) { message.value = `导入完成：新增 ${result.result.imported} 项，跳过 ${result.result.skipped} 项，恢复 ${result.result.knowledge} 个知识库。`; plan.value = null; files.value = []; if (fileInput.value) fileInput.value.value = ''; dirty.value = false; await refresh(); await refreshData(); await refreshNuxtData('site-workspace') }
  } catch (e: any) { message.value = e.data?.statusMessage || '连接中断，导入结果暂不确定；请查看操作记录并重新预览。'; if (action === 'apply') plan.value = null; await refreshData() }
  finally { importing.value = false; importAction.value = '' }
}
function discard() { if (workspace.value) form.value = structuredClone(toRaw(workspace.value.settings)); dirty.value = false; message.value = '已撤销未保存的设置' }
function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value || busy.value || importing.value || credentialBusy.value || credentialToken.value) { event.preventDefault(); event.returnValue = '' } }
onMounted(() => window.addEventListener('beforeunload', beforeUnload))
onBeforeUnmount(() => window.removeEventListener('beforeunload', beforeUnload))
onBeforeRouteLeave(() => {
  if (dirty.value) { message.value = '请先保存或撤销设置'; return false }
  if ((busy.value || importing.value || credentialBusy.value || credentialToken.value) && !window.confirm('操作仍在进行，或凭据尚未保存；离开后结果可能丢失。确定离开吗？')) return false
})
useSeoMeta({ title: '设置 — XIAOJUESHI' })
</script>
<style scoped>
.agent-credentials { margin-bottom: 22px; }
.agent-credentials [role='group'] { display: flex; flex-wrap: wrap; gap: 12px 22px; margin: 20px 0; }
.agent-credentials textarea { overflow-wrap: anywhere; word-break: break-all; }
</style>
<template><AdminShell><main class="workspace-page settings-page"><div class="workspace-page-heading"><div><div class="page-eyebrow">SETTINGS</div><h1>设置</h1><p>管理站点信息、外观、编辑偏好与数据。</p></div></div><div class="settings-tabs" role="tablist" aria-label="站点设置"><button v-for="option in [{ id: 'general', name: '基本信息', icon: Settings2 }, { id: 'appearance', name: '外观', icon: Sun }, { id: 'editor', name: '编辑与发布', icon: PenLine }, { id: 'data', name: '数据管理', icon: Database }]" :key="option.id" role="tab" :aria-selected="tab === option.id" :class="{ active: tab === option.id }" @click="changeTab(option.id)"><component :is="option.icon" :size="15" />{{ option.name }}</button></div><p v-if="message" class="notice" role="status">{{ message }}</p><p v-if="workspaceStatus === 'pending'" class="notice loading-inline" role="status"><span class="loading-spinner" aria-hidden="true" />正在加载设置…</p><div v-else-if="workspaceError" class="notice" role="alert">设置加载失败。<button @click="refresh()">重新加载</button></div>
<form v-if="form && tab !== 'data'" class="settings-form" @submit.prevent="save" @input="dirty = true" @change="dirty = true">
<section v-if="tab === 'general'" class="workspace-panel"><div class="panel-heading"><h2>基本信息</h2><span class="small-pill">公开站点</span></div><p>这些信息用于导航、页面标题和搜索摘要。</p><label class="form-field">站点名称<input v-model="form.name" required maxlength="80" /></label><label class="form-field">站点简介<textarea v-model="form.description" rows="3" maxlength="500" /></label><label class="form-field">SEO 默认标题<input v-model="form.seoTitle" required maxlength="150" /></label><label class="form-field">GitHub 链接<input v-model="form.github" type="url" placeholder="https://github.com/…" maxlength="300" /></label></section>
<section v-if="tab === 'appearance'" class="workspace-panel"><div class="panel-heading"><h2>默认外观</h2></div><p>前台与后台共用主题。访客主动选择的主题优先于站点默认值。</p><div class="theme-options" role="group" aria-label="站点默认主题"><button v-for="choice in choices" :key="choice.id" type="button" :aria-pressed="form.theme === choice.id" class="theme-option" :class="{ selected: form.theme === choice.id }" @click="form.theme = choice.id; dirty = true"><div class="theme-sample" :class="`sample-${choice.id}`"><span /><i /><i /><i /></div><div><component :is="choice.icon" :size="16" /><strong>{{ choice.name }}</strong><Check v-if="form.theme === choice.id" :size="15" /></div><small>{{ choice.caption }}</small></button></div><div class="personal-theme"><h3>当前设备</h3><p>当前选择：{{ choices.find(c => c.id === selection)?.name }}。可以即时预览，不需要保存站点设置。</p><div class="segmented"><button v-for="choice in choices" :key="choice.id" type="button" :class="{ active: selection === choice.id }" @click="setTheme(choice.id)">{{ choice.name }}</button></div><button type="button" class="subtle-button" @click="resetTheme">清除设备偏好，使用站点默认值</button></div></section>
<section v-if="tab === 'editor'" class="workspace-panel"><div class="panel-heading"><h2>编辑与发布</h2></div><p>保存编辑稿不会自动公开内容；新内容始终默认私密。</p><SelectField class="form-field" label="默认内容类型" accessible-label="默认内容类型" :model-value="form.defaultKind" :options="typeOptions" @change="setDefaultKind" /><label class="form-field">自动保存间隔（秒）<input v-model.number="form.autosaveSeconds" type="number" min="1" max="30" required /><small>支持 1–30 秒，编辑器会显示实际保存状态。</small></label><label class="settings-check"><input v-model="form.showReadingTime" type="checkbox" /><span><strong>显示阅读时长</strong><small>在公开文章列表与阅读页显示预计阅读时间。</small></span></label><label class="settings-check"><input v-model="form.codeWrap" type="checkbox" /><span><strong>代码块自动换行</strong><small>关闭时，长代码在代码块内横向滚动。</small></span></label></section>
<div class="settings-save-bar"><span>{{ dirty ? '有未保存的设置' : '设置已同步' }}</span><button v-if="dirty" type="button" class="button button-outline" @click="discard">撤销更改</button><button class="button button-dark" :disabled="busy || !dirty"><span v-if="busy" class="loading-spinner" aria-hidden="true" /><Check v-else :size="15" />{{ busy ? '正在保存…' : '保存设置' }}</button></div></form>
<section v-if="tab === 'data'" class="workspace-panel agent-credentials"><div class="panel-heading"><h2>Agent 凭据</h2></div><p>为当前实例创建有效期为 90 天的独立凭据。凭据不包含站点设置和备份权限，撤销后立即失效。</p><form class="inline-create" @submit.prevent="createCredential"><input v-model="credentialName" :disabled="credentialBusy" aria-label="凭据名称" placeholder="例如：我的 Mac" maxlength="80" required /><button class="button button-dark" :disabled="credentialBusy || Boolean(credentialToken) || !credentialName.trim() || !credentialScopes.length"><span v-if="credentialAction === 'create'" class="loading-spinner" aria-hidden="true" />{{ credentialAction === 'create' ? '正在创建…' : '创建凭据' }}</button></form><div role="group" aria-label="凭据权限"><label v-for="scope in credentialScopeOptions" :key="scope.id" class="settings-check"><input v-model="credentialScopes" :disabled="credentialBusy" type="checkbox" :value="scope.id" /><span>{{ scope.name }}</span></label></div><div v-if="credentialToken" class="import-plan" role="region" aria-label="新建凭据"><h3>请立即保存凭据</h3><p>密钥仅在创建后显示一次；请保存到本机钥匙串，不要粘贴到 Agent 对话。</p><label class="form-field">凭据<textarea :value="credentialToken" readonly rows="2" /></label><div class="panel-actions"><button type="button" class="button button-outline" @click="copyCredential">复制凭据</button><button type="button" class="button button-dark" @click="credentialToken = ''">我已保存</button></div></div><p v-if="credentialStatus === 'pending'" class="loading-inline" role="status"><span class="loading-spinner" aria-hidden="true" />正在加载凭据…</p><div v-else-if="credentialError" role="alert">凭据加载失败。<button class="text-link" @click="refreshAgentCredentials()">重新加载</button></div><template v-else><div v-for="credential in agentCredentials" :key="credential.id" class="operation-row"><div><strong>{{ credential.name }}</strong><p>{{ credential.revokedAt ? '已撤销' : credential.expiresAt <= Date.now() ? '已过期' : `有效至 ${new Date(credential.expiresAt).toISOString().slice(0, 10)} UTC` }}</p></div><button v-if="!credential.revokedAt" type="button" class="subtle-button" :disabled="credentialBusy" @click="revokeCredential(credential)"><span v-if="credentialId === credential.id" class="loading-spinner" aria-hidden="true" />{{ credentialId === credential.id ? '正在撤销…' : '撤销' }}</button></div><p v-if="!agentCredentials.length">暂无 Agent 凭据。</p></template></section>
<div v-if="tab === 'data'" class="data-management"><p v-if="dataStatus === 'pending'" class="loading-inline" role="status"><span class="loading-spinner" aria-hidden="true" />正在加载数据记录…</p><div v-else-if="dataError" class="notice" role="alert">数据记录加载失败。<button @click="refreshData()">重新加载</button></div><div v-else class="data-summary"><div v-for="metric in [{ name: '内容', value: dataInfo?.content }, { name: '知识库', value: dataInfo?.bases }, { name: '分类与标签', value: (dataInfo?.terms || 3) - 3 }, { name: '附件', value: dataInfo?.assets }]" :key="metric.name"><span>{{ metric.name }}</span><strong>{{ metric.value || 0 }}</strong></div></div><section class="workspace-panel"><div class="panel-heading"><h2>导出与备份</h2><Download :size="18" /></div><p>包含全部正文、编辑稿、发布版本、历史版本、目录、分类、标签、类型与站点设置。不包含管理员密码和会话。</p><div class="export-options"><a href="/api/admin/backup?format=zip" class="export-option"><div><h3>完整 ZIP</h3><p>Markdown 文件、JSON 元数据、原始图片与恢复清单，方便迁移。</p></div><Download :size="18" /></a><a href="/api/admin/backup" class="export-option"><div><h3>JSON 恢复包</h3><p>单个完整文件，适合备份和恢复到另一实例。</p></div><Download :size="18" /></a></div></section><section class="workspace-panel"><div class="panel-heading"><h2>导入与恢复</h2><Upload :size="18" /></div><p>支持多篇 Markdown，或单个本站 JSON / ZIP 备份，单次最多 100MB。先检查结果，再确认执行；现有内容不会被覆盖。</p><input ref="fileInput" class="import-file-input" type="file" :disabled="importing" accept=".md,.json,.zip" multiple aria-label="选择导入文件" @change="fileChanged" /><p v-if="files.length" class="file-selection">已选择 {{ files.length }} 个文件：{{ files.map(f => f.name).join('、') }}</p><label class="settings-check"><input v-model="restoreSettings" :disabled="importing" type="checkbox" /><span><strong>同时恢复备份中的站点设置</strong><small>默认保留当前站点名称、主题及编辑偏好。</small></span></label><button class="button button-outline" :disabled="importing || !files.length" @click="runImport('plan')"><span v-if="importAction === 'plan'" class="loading-spinner" aria-hidden="true" /><Upload v-else :size="15" />{{ importAction === 'plan' ? '正在预览…' : '预览导入结果' }}</button><div v-if="plan" class="import-plan" role="region" aria-label="导入预览"><h3>确认导入计划</h3><div class="import-plan-stats"><span>新增内容 <strong>{{ plan.add }}</strong></span><span>跳过内容 <strong>{{ plan.skip }}</strong></span><span>新增知识库 <strong>{{ plan.knowledge }}</strong></span><span>新增组织项 <strong>{{ plan.terms }}</strong></span><span>待检查附件 <strong>{{ plan.assets }}</strong></span></div><p v-if="plan.conflicts.length">以下内容链接冲突，将跳过：{{ plan.conflicts.join('、') }}</p><p>{{ plan.restoreSettings ? '将同时恢复站点设置。' : '保留本站现有设置。' }}执行过程中任一写入失败，将回滚本次导入。</p><div class="panel-actions"><button class="button button-outline" :disabled="importing" @click="plan = null">取消</button><button class="button button-dark" :disabled="importing" @click="runImport('apply')"><span v-if="importAction === 'apply'" class="loading-spinner" aria-hidden="true" />{{ importAction === 'apply' ? '正在导入…' : '确认执行导入' }}<ArrowUpRight v-if="importAction !== 'apply'" :size="15" /></button></div></div></section><section class="workspace-panel"><div class="panel-heading"><h2>操作记录</h2><button class="icon-button" aria-label="刷新数据记录" :disabled="dataStatus === 'pending'" :aria-busy="dataStatus === 'pending'" @click="refreshData()"><span v-if="dataStatus === 'pending'" class="loading-spinner" aria-hidden="true" /><RefreshCw v-else :size="17" /></button></div><p v-if="!dataInfo?.operations.length && !dataError && dataStatus !== 'pending'">暂无导入导出记录。</p><div v-for="(operation, index) in dataInfo?.operations" :key="index" class="operation-row"><span class="operation-dot" :class="{ failed: !operation.success }" /><div><strong>{{ operation.action }}</strong><p>{{ operation.detail }}</p></div><time>{{ operation.at.slice(0,16).replace('T',' ') }} UTC</time></div></section></div></main></AdminShell></template>
